            log.warn("Intento de acceso no autorizado a registro de mascota, rol: {}", rol);
            redirectAttributes.addFlashAttribute("error", "No tienes permiso para registrar mascotas");
            return "redirect:/mascotas/disponibles";
        }
        log.info("Mostrando formulario de registro de mascota");
        return "mascotas/formularioRegistroMascota";
    }

    /**
     * Registrar nueva mascota (Solo ADMIN)
     */
    @PostMapping("/registrar")
    public String registrarMascota(@Valid @ModelAttribute("mascota") Mascota mascota,
            BindingResult bindingResult,
            HttpSession session,
            RedirectAttributes redirectAttributes,
            Model model) {
        // Proteger endpoint: solo administradores pueden registrar mascotas
        String rol = (String) session.getAttribute("rol");
        if (!"ADMIN".equals(rol)) {
            log.warn("Intento de POST no autorizado a registro de mascota, rol: {}", rol);
            redirectAttributes.addFlashAttribute("error", "No tienes permiso para registrar mascotas");
            return "redirect:/mascotas/disponibles";
        }

        log.info("Registrando nueva mascota: {}", mascota.getNombre());

        if (bindingResult.hasErrors()) {
            log.warn("Errores en la validación del formulario");
            return "mascotas/formularioRegistroMascota";
        }

        try {
            Mascota mascotaRegistrada = mascotaService.registrarMascota(mascota);
            log.info("Mascota registrada exitosamente con ID: {}", mascotaRegistrada.getId());
            return "redirect:/mascotas/detalle/" + mascotaRegistrada.getId() + "?exito=true";
        } catch (Exception e) {
            log.error("Error al registrar mascota", e);
            model.addAttribute("error", "Error al registrar la mascota");
            return "mascotas/formularioRegistroMascota";
        }
    }

    /**
     * Mostrar detalle de mascota
     */
    @GetMapping("/detalle/{id}")
    public String mostrarDetalleMascota(@PathVariable Long id, Model model, RedirectAttributes redirectAttributes) {
        log.info("Mostrando detalle de mascota con ID: {}", id);

        try {
            return mascotaService.obtenerDatosMascota(id)
                    .map(mascota -> {
                        cargarDetalleMascota(
                                model,
                                mascota,
                                mascotaService.obtenerFotosMascota(id),
                                mascotaService.obtenerMascotasRelacionadas(id, LIMITE_MASCOTAS_RELACIONADAS));
                        return "mascotas/detalleMascota";
                    })
                    .orElseGet(() -> redirigirAListaDisponiblesConError(redirectAttributes));
        } catch (Exception e) {
            log.error("No fue posible cargar el detalle de la mascota con ID: {}", id, e);
            return redirigirAListaDisponiblesConError(redirectAttributes);
        }
    }

    private void cargarDetalleMascota(Model model, Mascota mascota, List<Foto> fotos, List<Mascota> relacionadas) {
        model.addAttribute("mascota", mascota);
        model.addAttribute("fotos", fotos);
        model.addAttribute("mascotasRelacionadas", relacionadas != null ? relacionadas : List.of());
    }

    private String redirigirAListaDisponiblesConError(RedirectAttributes redirectAttributes) {
        redirectAttributes.addFlashAttribute("error", MENSAJE_ERROR_DETALLE);
        return "redirect:/mascotas/disponibles";
    }

    /**
     * Mostrar formulario de edición (Solo ADMIN)
     */
    @GetMapping("/editar/{id}")
    public String mostrarFormularioEdicion(@PathVariable Long id,
                                          HttpSession session,
                                          RedirectAttributes redirectAttributes,
                                          Model model) {
        // Proteger endpoint: solo administradores pueden editar mascotas
        String rol = (String) session.getAttribute("rol");
        if (!"ADMIN".equals(rol)) {
            log.warn("Intento de acceso no autorizado a edición de mascota, rol: {}", rol);
            redirectAttributes.addFlashAttribute("error", "No tienes permiso para editar mascotas");
            return "redirect:/mascotas/disponibles";
        }

        log.info("Mostrando formulario de edición para mascota con ID: {}", id);

        Mascota mascota = mascotaService.obtenerMascotaPorId(id)
                .orElseThrow(() -> new RuntimeException("Mascota no encontrada con ID: " + id));

        model.addAttribute("mascota", mascota);
        return "mascotas/formularioEditarMascota";
    }

    /**
     * Actualizar mascota (Solo ADMIN)
     */
    @PostMapping("/actualizar/{id}")
    public String actualizarMascota(@PathVariable Long id,
            @Valid @ModelAttribute("mascota") Mascota mascota,
            BindingResult bindingResult,
            HttpSession session,
            RedirectAttributes redirectAttributes) {
        // Proteger endpoint: solo administradores pueden actualizar mascotas
        String rol = (String) session.getAttribute("rol");
        if (!"ADMIN".equals(rol)) {
            log.warn("Intento de POST no autorizado a actualización de mascota, rol: {}", rol);
            redirectAttributes.addFlashAttribute("error", "No tienes permiso para editar mascotas");
            return "redirect:/mascotas/disponibles";
        }
        log.info("Actualizando mascota con ID: {}", id);

        if (bindingResult.hasErrors()) {
            log.warn("Errores en la validación del formulario de actualización");
            return "mascotas/formularioEditarMascota";
        }

        try {
            mascotaService.actualizarMascota(id, mascota);
            log.info("Mascota actualizada exitosamente");
            return "redirect:/mascotas/detalle/" + id + "?exito=true";
        } catch (Exception e) {
            log.error("Error al actualizar mascota", e);
            return "redirect:/mascotas/detalle/" + id + "?error=true";
        }
    }

    /**
     * Eliminar mascota (Solo ADMIN)
     */
    @PostMapping("/eliminar/{id}")
    public String eliminarMascota(@PathVariable Long id,
                                 HttpSession session,
                                 RedirectAttributes redirectAttributes) {
        // Proteger endpoint: solo administradores pueden eliminar mascotas
        String rol = (String) session.getAttribute("rol");
        if (!"ADMIN".equals(rol)) {
            log.warn("Intento de POST no autorizado a eliminación de mascota, rol: {}", rol);
            redirectAttributes.addFlashAttribute("error", "No tienes permiso para eliminar mascotas");
            return "redirect:/mascotas/disponibles";
        }

        log.info("Eliminando mascota con ID: {}", id);

        try {
            mascotaService.eliminarMascota(id);
            log.info("Mascota eliminada exitosamente");
            redirectAttributes.addFlashAttribute("mensaje", "Mascota eliminada exitosamente");
            return "redirect:/mascotas/lista?exito=true";
        } catch (Exception e) {
            log.error("Error al eliminar mascota", e);
            redirectAttributes.addFlashAttribute("error", "Error al eliminar mascota");
            return "redirect:/mascotas/lista?error=true";
        }
    }


    /**
     * T.4.5 - Mostrar formulario de búsqueda por compatibilidad
     */
    @GetMapping("/buscar-compatible")
    public String mostrarFormularioFiltros() {
        log.info("Accediendo al formulario de búsqueda por compatibilidad");
        return "mascotas/filtrar";
    }

    /**
     * Buscar mascotas por nombre
     */
    @GetMapping("/buscar")
    public String buscarMascotas(@RequestParam(value = "nombre", required = false) String nombre, Model model) {
        log.info("Buscando mascotas con nombre: {}", nombre);

        List<Mascota> mascotas = StringUtils.hasText(nombre)
                ? mascotaService.buscarPorNombre(nombre)
                : mascotaService.obtenerTodasLasMascotas();

        model.addAttribute("mascotas", mascotas);
        model.addAttribute("nombre", nombre);
        model.addAttribute("totalMascotas", mascotas.size());
        return "mascotas/resultadosBusqueda";
    }

    /**
     * Cargar foto para mascota (Solo ADMIN)
     */
    @PostMapping("/cargarFoto/{mascotaId}")
    public String cargarFoto(@PathVariable Long mascotaId,
            @RequestParam("foto") MultipartFile file,
            HttpSession session,
            RedirectAttributes redirectAttributes) {
        // Proteger endpoint: solo administradores pueden cargar fotos
        String rol = (String) session.getAttribute("rol");
        if (!"ADMIN".equals(rol)) {
            log.warn("Intento de POST no autorizado a cargar foto de mascota, rol: {}", rol);
            redirectAttributes.addFlashAttribute("error", "No tienes permiso para cargar fotos");
            return "redirect:/mascotas/disponibles";
        }

        log.info("Cargando foto para mascota con ID: {}", mascotaId);

        try {
            if (file.isEmpty()) {
                log.warn("Archivo de foto vacío");
                redirectAttributes.addFlashAttribute("error", "Archivo vacío");
                return "redirect:/mascotas/detalle/" + mascotaId + "?error=archivo_vacio";
            }

            // Guardar archivo de foto en servidor
            String nombreArchivo = guardarArchivo(file);

            // Guardar objeto Foto asociado a una mascota
            guardarFotoMascota(mascotaId, nombreArchivo);

            log.info("Foto cargada exitosamente");
            redirectAttributes.addFlashAttribute("mensaje", "Foto cargada exitosamente");
            return "redirect:/mascotas/detalle/" + mascotaId + "?exito=true";
        } catch (IOException e) {
            log.error("Error al cargar foto", e);
            redirectAttributes.addFlashAttribute("error", "Error al cargar foto");
            return "redirect:/mascotas/detalle/" + mascotaId + "?error=true";
        }
    }

    private void guardarFotoMascota(Long mascotaId, String nombreArchivo) {
        Foto foto = new Foto();
        foto.setNombreArchivo(nombreArchivo);
        foto.setRutaFoto(UPLOAD_DIR + nombreArchivo);
        foto.setEsPrincipal(false);

        mascotaService.agregarFoto(mascotaId, foto);
    }

    private static String guardarArchivo(MultipartFile file) throws IOException {
        // Crear directorio si no existe
        Path uploadPath = Paths.get(UPLOAD_DIR);
        if (!Files.exists(uploadPath)) {
            Files.createDirectories(uploadPath);
        }

        // Generar nombre único para el archivo
        String nombreArchivo = System.currentTimeMillis() + "_" + file.getOriginalFilename();
        Path rutaArchivo = uploadPath.resolve(nombreArchivo);

        // Guardar archivo
        Files.write(rutaArchivo, file.getBytes());
        return nombreArchivo;
    }
}

package com.example.gr01_1bt3_622_26a.controller;

import com.example.gr01_1bt3_622_26a.entity.Solicitud;
import com.example.gr01_1bt3_622_26a.entity.Solicitante;
import com.example.gr01_1bt3_622_26a.entity.Mascota;
import com.example.gr01_1bt3_622_26a.service.SolicitudService;
import com.example.gr01_1bt3_622_26a.service.SolicitanteService;
import com.example.gr01_1bt3_622_26a.service.MascotaService;
import com.example.gr01_1bt3_622_26a.service.ContratoService;
import jakarta.servlet.http.HttpSession;
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.validation.BindingResult;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

@Controller
@RequestMapping("/solicitudes")
@RequiredArgsConstructor
@Slf4j
public class SolicitudController {

    private final SolicitudService solicitudService;
    private final SolicitanteService solicitanteService;
    private final MascotaService mascotaService;
    private final ContratoService contratoService;

    @GetMapping("/formulario")
    public String mostrarFormulario(
            @RequestParam(value = "mascotaId", required = false) Long mascotaId,
            Model model) {

        Mascota mascotaPreSeleccionada = null;

        // Si viene mascotaId en la URL, pre-cargar la mascota
        if (mascotaId != null) {
            Optional<Mascota> mascotaOpt = mascotaService.obtenerPorId(mascotaId);
            if (mascotaOpt.isPresent()) {
                mascotaPreSeleccionada = mascotaOpt.get();
                log.info("Mascota pre-seleccionada: {} (ID: {})", mascotaPreSeleccionada.getNombre(), mascotaId);
            }
        }

        // Crear una nueva solicitud con la mascota pre-seleccionada si es aplicable
        Solicitud solicitud = new Solicitud();
        if (mascotaPreSeleccionada != null) {
            // Inicializar la mascota en la solicitud
            solicitud.setMascota(mascotaPreSeleccionada);
        }

        // Agregar datos al modelo
        if (mascotaPreSeleccionada != null) {
            // Si hay mascota pre-seleccionada, NO incluir lista de mascotas
            model.addAttribute("mascotaPreSeleccionada", mascotaPreSeleccionada);
            model.addAttribute("tieneMascotaPreSeleccionada", true);
        } else {
            // Si no hay pre-selección, mostrar lista de mascotas disponibles
            List<Mascota> mascotas = mascotaService.obtenerDisponibles();
            model.addAttribute("mascotas", mascotas);
            model.addAttribute("tieneMascotaPreSeleccionada", false);
        }

        model.addAttribute("solicitud", solicitud);
        return "solicitudes/formularioSolicitud";
    }

    /**
     * TAREA 3: Proteger endpoint POST /solicitudes/crear
     * TAREA 4: Agregar validación con BindingResult
     * TAREA 5: Obtener solicitante desde HttpSession
     *
     * Crea una nueva solicitud de adopción validando todos los campos.
     * El ID del solicitante se obtiene de la sesión del usuario (TAREA 3 - Seguridad)
     * para evitar que alguien envíe solicitudes en nombre de otro usuario.
     *
     * @param solicitud Objeto con datos del formulario, validado con anotaciones.
     * @param bindingResult Captura errores de validación (TAREA 4)
     * @param session Sesión HTTP para obtener solicitar desde usuario autenticado (TAREA 3)
     * @param redirectAttributes Para pasar mensajes de éxito/error
     * @return Vista de redirección con resultado
     */
    @PostMapping("/crear")
    public String crearSolicitud(
            @Valid @ModelAttribute("solicitud") Solicitud solicitud,
            BindingResult bindingResult,
            HttpSession session,
            RedirectAttributes redirectAttributes) {

        log.info("Intento de crear solicitud");

        // TAREA 4: Validar errores de validación del formulario
        if (bindingResult.hasErrors()) {
            log.warn("Errores de validación en formulario de solicitud: {}", bindingResult.getAllErrors());
            // El formulario se vuelve a mostrar con los errores
            return "solicitudes/formularioSolicitud";
        }

        // TAREA 3: Obtener solicitante de la sesión (seguridad)
        Long solicitanteId = (Long) session.getAttribute("solicitanteId");

        if (solicitanteId == null) {
            log.warn("Intento de crear solicitud sin sesión de usuario");
            redirectAttributes.addFlashAttribute("error", "Debe iniciar sesión para crear una solicitud");
            return "redirect:/solicitudes/formulario";
        }

        Optional<Solicitante> solicitante = solicitanteService.obtenerPorId(solicitanteId);
        Optional<Mascota> mascota = mascotaService.obtenerPorId(solicitud.getMascota().getId());

        if (solicitante.isPresent() && mascota.isPresent()) {
            solicitud.setSolicitante(solicitante.get());
            solicitud.setMascota(mascota.get());

            try {
                Solicitud savedSolicitud = solicitudService.crearSolicitud(solicitud);
                log.info("Solicitud creada exitosamente: {}", savedSolicitud.getId());
                redirectAttributes.addFlashAttribute("mensaje", "Solicitud creada exitosamente");
                return "redirect:/solicitudes/" + savedSolicitud.getId();
            } catch (Exception e) {
                log.error("Error al crear solicitud", e);
                redirectAttributes.addFlashAttribute("error", "Error al procesar la solicitud");
                return "redirect:/solicitudes/formulario";
            }
        }

        log.warn("Solicitante o Mascota no encontrados");
        redirectAttributes.addFlashAttribute("error", "Error al crear la solicitud");
        return "redirect:/solicitudes/formulario";
    }

    /**
     * TAREA 1: Listar solicitudes asociadas al solicitante
     *
     * Obtiene todas las solicitudes del usuario autenticado desde la sesión.
     * Implementa el método obtenerSolicitudesDelSolicitante del servicio.
     *
     * @param session Sesión HTTP del usuario autenticado
     * @param model Modelo para pasar datos a la vista
     * @return Vista con lista de solicitudes del solicitante
     */
    @GetMapping("/mis-solicitudes")
    public String listarMisSolicitudes(HttpSession session, Model model) {
        Long solicitanteId = (Long) session.getAttribute("solicitanteId");

        if (solicitanteId == null) {
            log.warn("Intento de acceder a solicitudes sin sesión de usuario");
            return "redirect:/login";
        }

        log.info("Listando solicitudes del solicitante: {}", solicitanteId);
        List<Solicitud> solicitudes = solicitudService.obtenerSolicitudesDelSolicitante(solicitanteId);

        model.addAttribute("solicitudes", solicitudes);
        model.addAttribute("titulo", "Mis Solicitudes");
        return "solicitudes/listaSolicitudes";
    }

    /**
     * TAREA 2: Consultar el detalle de una solicitud específica
     *
     * Obtiene el detalle de una solicitud validando que el solicitante sea el propietario.
     * Implementa el método obtenerDetalleSolicitud del servicio con validación de seguridad.
     *
     * Modificación: Ahora valida que el solicitante sea el propietario de la solicitud
     * antes de mostrar el detalle.
     *
     * @param id ID de la solicitud
     * @param session Sesión HTTP para validar propietario
     * @param model Modelo para pasar datos a la vista
     * @param redirectAttributes Para pasar mensajes de error
     * @return Vista del detalle si es propietario, redirección en otro caso
     */
    @GetMapping("/{id}")
    public String verDetalle(
            @PathVariable Long id,
            HttpSession session,
            Model model,
            RedirectAttributes redirectAttributes) {

        Long solicitanteId = (Long) session.getAttribute("solicitanteId");

        if (solicitanteId == null) {
            log.warn("Intento de ver solicitud sin sesión de usuario");
            return "redirect:/login";
        }

        log.info("Consultando detalle de solicitud {} para solicitante {}", id, solicitanteId);

        // TAREA 2: Usar obtenerDetalleSolicitud que valida propietario
        Optional<Solicitud> solicitud = solicitudService.obtenerDetalleSolicitud(id, solicitanteId);

        if (solicitud.isPresent()) {
            model.addAttribute("solicitud", solicitud.get());
            return "solicitudes/detalleSolicitud";
        }

        log.warn("Solicitud {} no encontrada o solicitante {} no es el propietario", id, solicitanteId);
        redirectAttributes.addFlashAttribute("error", "No tienes permiso para ver esta solicitud");
        return "redirect:/solicitudes/mis-solicitudes";
    }

    @GetMapping("/pendientes/lista")
    public String listarPendientes(Model model) {
        List<Solicitud> pendientes = solicitudService.obtenerPorEstado("Pendiente");
        model.addAttribute("solicitudes", pendientes);
        model.addAttribute("titulo", "Solicitudes Pendientes");
        return "solicitudes/listaSolicitudes";
    }

    @GetMapping("/solicitante/{solicitanteId}")
    public String listarSolicitante(@PathVariable Long solicitanteId, Model model) {
        List<Solicitud> solicitudes = solicitudService.obtenerPorSolicitante(solicitanteId);
        model.addAttribute("solicitudes", solicitudes);
        return "solicitudes/listaSolicitudes";
    }

    @PostMapping("/{id}/aprobar")
    public ResponseEntity<?> aprobarSolicitud(@PathVariable Long id,
                                   @RequestParam(required = false) String observaciones) {
        try {
            Solicitud solicitud = solicitudService.aprobarSolicitud(id, observaciones != null ? observaciones : "");
            if (solicitud != null) {
                log.info("Solicitud {} aprobada exitosamente", id);
                Map<String, String> response = new HashMap<>();
                response.put("mensaje", "Solicitud aprobada exitosamente");
                return ResponseEntity.ok(response);
            }
        } catch (Exception e) {
            log.error("Error al aprobar solicitud {}: {}", id, e.getMessage());
            Map<String, String> error = new HashMap<>();
            error.put("error", "Error al aprobar solicitud: " + e.getMessage());
            return ResponseEntity.badRequest().body(error);
        }
        Map<String, String> error = new HashMap<>();
        error.put("error", "No se pudo aprobar la solicitud");
        return ResponseEntity.badRequest().body(error);
    }

    @PostMapping("/{id}/rechazar")
    public ResponseEntity<?> rechazarSolicitud(@PathVariable Long id,
                                   @RequestParam String razon) {
        try {
            if (razon == null || razon.trim().isEmpty()) {
                log.warn("Intento de rechazar solicitud {} sin razón", id);
                Map<String, String> error = new HashMap<>();
                error.put("error", "Debes proporcionar una razón para rechazar");
                return ResponseEntity.badRequest().body(error);
            }

            Solicitud solicitud = solicitudService.rechazarSolicitud(id, razon);
            if (solicitud != null) {
                log.info("Solicitud {} rechazada exitosamente", id);
                Map<String, String> response = new HashMap<>();
                response.put("mensaje", "Solicitud rechazada exitosamente");
                return ResponseEntity.ok(response);
            }
        } catch (Exception e) {
            log.error("Error al rechazar solicitud {}: {}", id, e.getMessage());
            Map<String, String> error = new HashMap<>();
            error.put("error", "Error al rechazar solicitud: " + e.getMessage());
            return ResponseEntity.badRequest().body(error);
        }
        Map<String, String> error = new HashMap<>();
        error.put("error", "No se pudo rechazar la solicitud");
        return ResponseEntity.badRequest().body(error);
    }

    @PostMapping("/{id}/enviar-a-revision")
    public ResponseEntity<?> enviarARevision(@PathVariable Long id,
                                 @RequestParam(required = false) String observaciones) {
        try {
            log.info("Enviando solicitud {} a revisión", id);

            // Obtener la solicitud actual
            Optional<Solicitud> solicitudOpt = solicitudService.obtenerPorId(id);
            if (solicitudOpt.isEmpty()) {
                log.warn("Solicitud {} no encontrada", id);
                Map<String, String> error = new HashMap<>();
                error.put("error", "Solicitud no encontrada");
                return ResponseEntity.badRequest().body(error);
            }

            Solicitud solicitud = solicitudOpt.get();
            solicitud.setEstado("En revisión");
            if (observaciones != null && !observaciones.trim().isEmpty()) {
                solicitud.setObservaciones(observaciones);
            }

            solicitudService.actualizarSolicitud(solicitud);
            log.info("Solicitud {} enviada a revisión exitosamente", id);
            Map<String, String> response = new HashMap<>();
            response.put("mensaje", "Solicitud enviada a revisión exitosamente");
            return ResponseEntity.ok(response);

        } catch (Exception e) {
            log.error("Error al enviar solicitud {} a revisión: {}", id, e.getMessage());
            Map<String, String> error = new HashMap<>();
            error.put("error", "Error al enviar a revisión: " + e.getMessage());
            return ResponseEntity.badRequest().body(error);
        }
    }
}

package com.example.gr01_1bt3_622_26a.controller;

import com.example.gr01_1bt3_622_26a.entity.Solicitud;
import com.example.gr01_1bt3_622_26a.entity.Solicitante;
import com.example.gr01_1bt3_622_26a.entity.Mascota;
import com.example.gr01_1bt3_622_26a.service.SolicitudService;
import com.example.gr01_1bt3_622_26a.service.SolicitanteService;
import com.example.gr01_1bt3_622_26a.service.MascotaService;
import com.example.gr01_1bt3_622_26a.service.ContratoService;
import jakarta.servlet.http.HttpSession;
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.validation.BindingResult;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

@Controller
@RequestMapping("/solicitudes")
@RequiredArgsConstructor
@Slf4j
public class SolicitudController {

    private final SolicitudService solicitudService;
    private final SolicitanteService solicitanteService;
    private final MascotaService mascotaService;
    private final ContratoService contratoService;

    @GetMapping("/formulario")
    public String mostrarFormulario(
            @RequestParam(value = "mascotaId", required = false) Long mascotaId,
            Model model) {

        Mascota mascotaPreSeleccionada = null;

        // Si viene mascotaId en la URL, pre-cargar la mascota
        if (mascotaId != null) {
            Optional<Mascota> mascotaOpt = mascotaService.obtenerPorId(mascotaId);
            if (mascotaOpt.isPresent()) {
                mascotaPreSeleccionada = mascotaOpt.get();
                log.info("Mascota pre-seleccionada: {} (ID: {})", mascotaPreSeleccionada.getNombre(), mascotaId);
            }
        }

        // Crear una nueva solicitud con la mascota pre-seleccionada si es aplicable
        Solicitud solicitud = new Solicitud();
        if (mascotaPreSeleccionada != null) {
            // Inicializar la mascota en la solicitud
            solicitud.setMascota(mascotaPreSeleccionada);
        }

        // Agregar datos al modelo
        if (mascotaPreSeleccionada != null) {
            // Si hay mascota pre-seleccionada, NO incluir lista de mascotas
            model.addAttribute("mascotaPreSeleccionada", mascotaPreSeleccionada);
            model.addAttribute("tieneMascotaPreSeleccionada", true);
        } else {
            // Si no hay pre-selección, mostrar lista de mascotas disponibles
            List<Mascota> mascotas = mascotaService.obtenerDisponibles();
            model.addAttribute("mascotas", mascotas);
            model.addAttribute("tieneMascotaPreSeleccionada", false);
        }

        model.addAttribute("solicitud", solicitud);
        return "solicitudes/formularioSolicitud";
    }

    /**
     * TAREA 3: Proteger endpoint POST /solicitudes/crear
     * TAREA 4: Agregar validación con BindingResult
     * TAREA 5: Obtener solicitante desde HttpSession
     *
     * Crea una nueva solicitud de adopción validando todos los campos.
     * El ID del solicitante se obtiene de la sesión del usuario (TAREA 3 - Seguridad)
     * para evitar que alguien envíe solicitudes en nombre de otro usuario.
     *
     * @param solicitud Objeto con datos del formulario, validado con anotaciones.
     * @param bindingResult Captura errores de validación (TAREA 4)
     * @param session Sesión HTTP para obtener solicitar desde usuario autenticado (TAREA 3)
     * @param redirectAttributes Para pasar mensajes de éxito/error
     * @return Vista de redirección con resultado
     */
    @PostMapping("/crear")
    public String crearSolicitud(
            @Valid @ModelAttribute("solicitud") Solicitud solicitud,
            BindingResult bindingResult,
            HttpSession session,
            RedirectAttributes redirectAttributes) {

        log.info("Intento de crear solicitud");

        // TAREA 4: Validar errores de validación del formulario
        if (bindingResult.hasErrors()) {
            log.warn("Errores de validación en formulario de solicitud: {}", bindingResult.getAllErrors());
            // El formulario se vuelve a mostrar con los errores
            return "solicitudes/formularioSolicitud";
        }

        // TAREA 3: Obtener solicitante de la sesión (seguridad)
        Long solicitanteId = (Long) session.getAttribute("solicitanteId");

        if (solicitanteId == null) {
            log.warn("Intento de crear solicitud sin sesión de usuario");
            redirectAttributes.addFlashAttribute("error", "Debe iniciar sesión para crear una solicitud");
            return "redirect:/solicitudes/formulario";
        }

        Optional<Solicitante> solicitante = solicitanteService.obtenerPorId(solicitanteId);
        Optional<Mascota> mascota = mascotaService.obtenerPorId(solicitud.getMascota().getId());

        if (solicitante.isPresent() && mascota.isPresent()) {
            solicitud.setSolicitante(solicitante.get());
            solicitud.setMascota(mascota.get());

            try {
                Solicitud savedSolicitud = solicitudService.crearSolicitud(solicitud);
                log.info("Solicitud creada exitosamente: {}", savedSolicitud.getId());
                redirectAttributes.addFlashAttribute("mensaje", "Solicitud creada exitosamente");
                return "redirect:/solicitudes/" + savedSolicitud.getId();
            } catch (Exception e) {
                log.error("Error al crear solicitud", e);
                redirectAttributes.addFlashAttribute("error", "Error al procesar la solicitud");
                return "redirect:/solicitudes/formulario";
            }
        }

        log.warn("Solicitante o Mascota no encontrados");
        redirectAttributes.addFlashAttribute("error", "Error al crear la solicitud");
        return "redirect:/solicitudes/formulario";
    }

    /**
     * TAREA 1: Listar solicitudes asociadas al solicitante
     *
     * Obtiene todas las solicitudes del usuario autenticado desde la sesión.
     * Implementa el método obtenerSolicitudesDelSolicitante del servicio.
     *
     * @param session Sesión HTTP del usuario autenticado
     * @param model Modelo para pasar datos a la vista
     * @return Vista con lista de solicitudes del solicitante
     */
    @GetMapping("/mis-solicitudes")
    public String listarMisSolicitudes(HttpSession session, Model model) {
        Long solicitanteId = (Long) session.getAttribute("solicitanteId");

        if (solicitanteId == null) {
            log.warn("Intento de acceder a solicitudes sin sesión de usuario");
            return "redirect:/login";
        }

        log.info("Listando solicitudes del solicitante: {}", solicitanteId);
        List<Solicitud> solicitudes = solicitudService.obtenerSolicitudesDelSolicitante(solicitanteId);

        model.addAttribute("solicitudes", solicitudes);
        model.addAttribute("titulo", "Mis Solicitudes");
        return "solicitudes/listaSolicitudes";
    }

    /**
     * TAREA 2: Consultar el detalle de una solicitud específica
     *
     * Obtiene el detalle de una solicitud validando que el solicitante sea el propietario.
     * Implementa el método obtenerDetalleSolicitud del servicio con validación de seguridad.
     *
     * Modificación: Ahora valida que el solicitante sea el propietario de la solicitud
     * antes de mostrar el detalle.
     *
     * @param id ID de la solicitud
     * @param session Sesión HTTP para validar propietario
     * @param model Modelo para pasar datos a la vista
     * @param redirectAttributes Para pasar mensajes de error
     * @return Vista del detalle si es propietario, redirección en otro caso
     */
    @GetMapping("/{id}")
    public String verDetalle(
            @PathVariable Long id,
            HttpSession session,
            Model model,
            RedirectAttributes redirectAttributes) {

        Long solicitanteId = (Long) session.getAttribute("solicitanteId");

        if (solicitanteId == null) {
            log.warn("Intento de ver solicitud sin sesión de usuario");
            return "redirect:/login";
        }

        log.info("Consultando detalle de solicitud {} para solicitante {}", id, solicitanteId);

        // TAREA 2: Usar obtenerDetalleSolicitud que valida propietario
        Optional<Solicitud> solicitud = solicitudService.obtenerDetalleSolicitud(id, solicitanteId);

        if (solicitud.isPresent()) {
            model.addAttribute("solicitud", solicitud.get());
            return "solicitudes/detalleSolicitud";
        }

        log.warn("Solicitud {} no encontrada o solicitante {} no es el propietario", id, solicitanteId);
        redirectAttributes.addFlashAttribute("error", "No tienes permiso para ver esta solicitud");
        return "redirect:/solicitudes/mis-solicitudes";
    }

    @GetMapping("/pendientes/lista")
    public String listarPendientes(Model model) {
        List<Solicitud> pendientes = solicitudService.obtenerPorEstado("Pendiente");
        model.addAttribute("solicitudes", pendientes);
        model.addAttribute("titulo", "Solicitudes Pendientes");
        return "solicitudes/listaSolicitudes";
    }

    @GetMapping("/solicitante/{solicitanteId}")
    public String listarSolicitante(@PathVariable Long solicitanteId, Model model) {
        List<Solicitud> solicitudes = solicitudService.obtenerPorSolicitante(solicitanteId);
        model.addAttribute("solicitudes", solicitudes);
        return "solicitudes/listaSolicitudes";
    }

    @PostMapping("/{id}/aprobar")
    public ResponseEntity<?> aprobarSolicitud(@PathVariable Long id,
                                   @RequestParam(required = false) String observaciones) {
        try {
            Solicitud solicitud = solicitudService.aprobarSolicitud(id, observaciones != null ? observaciones : "");
            if (solicitud != null) {
                log.info("Solicitud {} aprobada exitosamente", id);
                Map<String, String> response = new HashMap<>();
                response.put("mensaje", "Solicitud aprobada exitosamente");
                return ResponseEntity.ok(response);
            }
        } catch (Exception e) {
            log.error("Error al aprobar solicitud {}: {}", id, e.getMessage());
            Map<String, String> error = new HashMap<>();
            error.put("error", "Error al aprobar solicitud: " + e.getMessage());
            return ResponseEntity.badRequest().body(error);
        }
        Map<String, String> error = new HashMap<>();
        error.put("error", "No se pudo aprobar la solicitud");
        return ResponseEntity.badRequest().body(error);
    }

    @PostMapping("/{id}/rechazar")
    public ResponseEntity<?> rechazarSolicitud(@PathVariable Long id,
                                   @RequestParam String razon) {
        try {
            if (razon == null || razon.trim().isEmpty()) {
                log.warn("Intento de rechazar solicitud {} sin razón", id);
                Map<String, String> error = new HashMap<>();
                error.put("error", "Debes proporcionar una razón para rechazar");
                return ResponseEntity.badRequest().body(error);
            }

            Solicitud solicitud = solicitudService.rechazarSolicitud(id, razon);
            if (solicitud != null) {
                log.info("Solicitud {} rechazada exitosamente", id);
                Map<String, String> response = new HashMap<>();
                response.put("mensaje", "Solicitud rechazada exitosamente");
                return ResponseEntity.ok(response);
            }
        } catch (Exception e) {
            log.error("Error al rechazar solicitud {}: {}", id, e.getMessage());
            Map<String, String> error = new HashMap<>();
            error.put("error", "Error al rechazar solicitud: " + e.getMessage());
            return ResponseEntity.badRequest().body(error);
        }
        Map<String, String> error = new HashMap<>();
        error.put("error", "No se pudo rechazar la solicitud");
        return ResponseEntity.badRequest().body(error);
    }

    @PostMapping("/{id}/enviar-a-revision")
    public ResponseEntity<?> enviarARevision(@PathVariable Long id,
                                 @RequestParam(required = false) String observaciones) {
        try {
            log.info("Enviando solicitud {} a revisión", id);

            // Obtener la solicitud actual
            Optional<Solicitud> solicitudOpt = solicitudService.obtenerPorId(id);
            if (solicitudOpt.isEmpty()) {
                log.warn("Solicitud {} no encontrada", id);
                Map<String, String> error = new HashMap<>();
                error.put("error", "Solicitud no encontrada");
                return ResponseEntity.badRequest().body(error);
            }

            Solicitud solicitud = solicitudOpt.get();
            solicitud.setEstado("En revisión");
            if (observaciones != null && !observaciones.trim().isEmpty()) {
                solicitud.setObservaciones(observaciones);
            }

            solicitudService.actualizarSolicitud(solicitud);
            log.info("Solicitud {} enviada a revisión exitosamente", id);
            Map<String, String> response = new HashMap<>();
            response.put("mensaje", "Solicitud enviada a revisión exitosamente");
            return ResponseEntity.ok(response);

        } catch (Exception e) {
            log.error("Error al enviar solicitud {} a revisión: {}", id, e.getMessage());
            Map<String, String> error = new HashMap<>();
            error.put("error", "Error al enviar a revisión: " + e.getMessage());
            return ResponseEntity.badRequest().body(error);
        }
    }

    /**
     * Descarga el contrato PDF de una solicitud aprobada
     *
     * Endpoint: GET /solicitudes/{id}/contrato/descargar
     * Solo permite descargar si la solicitud está Aprobada
     *
     * @param id ID de la solicitud
     * @return PDF del contrato o error 404/403
     */
    @GetMapping("/{id}/contrato/descargar")
    public ResponseEntity<?> descargarContratoSolicitud(@PathVariable Long id) {
        log.info("Solicitud de descarga de contrato para solicitud ID: {}", id);

        try {
            // Verificar que la solicitud existe
            Optional<Solicitud> solicitudOpt = solicitudService.obtenerPorId(id);
            if (solicitudOpt.isEmpty()) {
                log.warn("Intento de descargar contrato para solicitud inexistente: {}", id);
                return ResponseEntity.notFound().build();
            }

            Solicitud solicitud = solicitudOpt.get();

            // Verificar que esté aprobada
            if (!"Aprobada".equals(solicitud.getEstado())) {
                log.warn("Intento de descargar contrato para solicitud no aprobada. ID: {}, Estado: {}", 
                    id, solicitud.getEstado());
                return ResponseEntity.status(HttpStatus.FORBIDDEN)
                    .body("El contrato solo puede descargarse si la solicitud ha sido aprobada");
            }

            // Para generar el PDF de la solicitud, usamos el método que referencia a una adopción
            // Si no existe adopción, generamos desde la solicitud directamente
            byte[] pdfContent = contratoService.generarContratoPDFDesdeSolicitud(id);

            if (pdfContent == null || pdfContent.length == 0) {
                log.error("PDF generado vacío para solicitud ID: {}", id);
                return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                    .body("Error: No se pudo generar el PDF del contrato");
            }

            // Construir headers HTTP
            String nombreArchivo = String.format("contrato_adopcion_solicitud_%d.pdf", id);

            HttpHeaders headers = new HttpHeaders();
            headers.setContentType(MediaType.APPLICATION_PDF);
            headers.setContentDispositionFormData("attachment", nombreArchivo);
            headers.setContentLength(pdfContent.length);

            log.info("Contrato PDF descargado para solicitud ID: {} - Tamaño: {} bytes",
                id, pdfContent.length);

            return ResponseEntity.ok()
                    .headers(headers)
                    .body(pdfContent);

        } catch (RuntimeException e) {
            log.error("Error al descargar contrato para solicitud ID: {}", id, e);
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                    .body("Error al generar el contrato: " + e.getMessage());
        }
    }
}

package com.example.gr01_1bt3_622_26a.service;

import com.example.gr01_1bt3_622_26a.entity.Solicitud;
import com.example.gr01_1bt3_622_26a.repository.SolicitudRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.Optional;

@Service
@RequiredArgsConstructor
@Transactional
@Slf4j
public class SolicitudService {

    private final SolicitudRepository solicitudRepository;

    // Constantes de estado para evitar hardcoding
    private static final String ESTADO_EN_REVISION = "En revisión";
    private static final String ESTADO_APROBADA = "Aprobada";
    private static final String ESTADO_RECHAZADA = "Rechazada";

    /**
     *  REFACTOR: crearSolicitud mejorado
     *
     * Responsabilidades:
     * - Validar que la solicitud no sea nula
     * - Asignar automáticamente el estado "En revisión" (regla de negocio)
     * - Registrar en logs la creación
     * - Guardar la solicitud en la BD
     * - Retornar la solicitud creada
     *
     * Validaciones:
     * - Solicitud no puede ser null
     * - Se asigna estado automáticamente (cliente no puede definirlo)
     *
     * Logging:
     * - INFO: Solicitud creada exitosamente
     * - ERROR: Si hay error en persistencia
     *
     * @param solicitud la solicitud a crear (sin estado)
     * @return la solicitud guardada con estado "En revisión"
     * @throws IllegalArgumentException si solicitud es null
     */
    public Solicitud crearSolicitud(Solicitud solicitud) {
        // Validación: solicitud no puede ser nula
        if (solicitud == null) {
            log.warn("Intento de crear solicitud con valor null");
            throw new IllegalArgumentException("La solicitud no puede ser nula");
        }

        try {
            // Regla de negocio: toda solicitud nueva inicia en "En revisión"
            solicitud.setEstado(ESTADO_EN_REVISION);

            // Guardar en BD
            Solicitud solicitudGuardada = solicitudRepository.save(solicitud);

            // Logging: auditoría de creación
            Long solicitanteId = solicitudGuardada.getSolicitante() != null ?
                    solicitudGuardada.getSolicitante().getId() : null;
            log.info("Solicitud creada exitosamente con ID: {} para solicitante: {}",
                    solicitudGuardada.getId(), solicitanteId);

            return solicitudGuardada;

        } catch (Exception e) {
            Long solicitanteId = solicitud.getSolicitante() != null ?
                    solicitud.getSolicitante().getId() : null;
            log.error("Error al crear solicitud para solicitante: {}",
                    solicitanteId, e);
            throw new RuntimeException("No fue posible crear la solicitud. Por favor intente nuevamente.", e);
        }
    }

    @Transactional(readOnly = true)
    public Optional<Solicitud> obtenerPorId(Long id) {
        return solicitudRepository.findById(id);
    }

    @Transactional(readOnly = true)
    public List<Solicitud> obtenerPorSolicitante(Long solicitanteId) {
        return solicitudRepository.findBySolicitanteId(solicitanteId);
    }

    /**
     *  REFACTOR: Obtener solicitudes del solicitante
     *
     * TAREA 1: Listar solicitudes asociadas al solicitante
     *
     * Responsabilidades:
     * - Validar que el solicitanteId sea válido (positivo y no nulo)
     * - Buscar todas las solicitudes asociadas al solicitante
     * - Retornar lista nunca nula (puede estar vacía)
     * - Registrar en logs para auditoría
     *
     * Comportamiento:
     * - Acepta cualquier ID (positivo, cero o negativo)
     * - Si no hay solicitudes, retorna lista vacía (nunca null)
     * - Nivel de aislamiento: READ-ONLY para evitar modificaciones
     *
     * Casos de uso:
     * - Listar mis solicitudes (solicitante viendo su historial)
     * - Consultar solicitudes pendientes de un solicitante
     *
     * @param solicitanteId ID del solicitante propietario
     * @return Lista de Solicitud (nunca nula, puede estar vacía)
     */
    @Transactional(readOnly = true)
    public List<Solicitud> obtenerSolicitudesDelSolicitante(Long solicitanteId) {
        log.debug("Obteniendo solicitudes para solicitante ID: {}", solicitanteId);

        List<Solicitud> solicitudes = obtenerPorSolicitante(solicitanteId);

        log.info("Se encontraron {} solicitudes para solicitante ID: {}",
                solicitudes.size(), solicitanteId);

        return solicitudes;
    }

    @Transactional(readOnly = true)
    public List<Solicitud> obtenerPorMascota(Long mascotaId) {
        return solicitudRepository.findByMascotaId(mascotaId);
    }

    @Transactional(readOnly = true)
    public List<Solicitud> obtenerPorEstado(String estado) {
        return solicitudRepository.findByEstadoOrderByFecha(estado);
    }

    public Solicitud aprobarSolicitud(Long id) {
        log.info("Aprobando solicitud con ID: {}", id);
        return solicitudRepository.findById(id)
                .map(s -> {
                    s.setEstado(ESTADO_APROBADA);
                    Solicitud actualizada = solicitudRepository.save(s);
                    log.info("Solicitud {} aprobada exitosamente", id);
                    return actualizada;
                })
                .orElseGet(() -> {
                    log.warn("Intento de aprobar solicitud no existente con ID: {}", id);
                    return null;
                });
    }

    public Solicitud rechazarSolicitud(Long id, String razon) {
        log.info("Rechazando solicitud con ID: {} - Razón: {}", id, razon);
        return solicitudRepository.findById(id)
                .map(s -> {
                    s.setEstado(ESTADO_RECHAZADA);
                    s.setRazonRechazo(razon);
                    Solicitud actualizada = solicitudRepository.save(s);
                    log.info("Solicitud {} rechazada exitosamente", id);
                    return actualizada;
                })
                .orElseGet(() -> {
                    log.warn("Intento de rechazar solicitud no existente con ID: {}", id);
                    return null;
                });
    }

    public Solicitud actualizarSolicitud(Solicitud solicitud) {
        return solicitudRepository.save(solicitud);
    }

    @Transactional(readOnly = true)
    public List<Solicitud> obtenerTodas() {
        return solicitudRepository.findAll();
    }

    @Transactional(readOnly = true)
    public long contarPendientesParaMascota(Long mascotaId) {
        return solicitudRepository.countPendientesForMascota(mascotaId);
    }

    /**
     *  REFACTOR: Obtener detalle de solicitud con validación de propietario
     *
     * TAREA 2: Consultar el detalle de una solicitud específica
     *
     * Responsabilidades:
     * - Validar que ambos parámetros sean válidos (positivos y no nulos)
     * - Buscar la solicitud por ID
     * - Validar que el solicitante sea el propietario (seguridad)
     * - Retornar Optional con la solicitud o empty si no es propietario
     * - Registrar en logs intentos de acceso no autorizado
     *
     * Comportamiento:
     * - Retorna Optional.of(Solicitud) si el solicitante es propietario
     * - Retorna Optional.empty() si:
     *   1. La solicitud no existe
     *   2. El solicitante NO es el propietario (seguridad)
     * - Valida parámetros antes de consultar BD
     * - Registra accesos denegados para auditoría
     *
     * Validaciones de Seguridad:
     * - Previene que un solicitante vea solicitudes de otros
     * - Logging de intentos de acceso no autorizado
     *
     * Casos de uso:
     * - Un solicitante consultando el detalle de su propia solicitud
     * - Sistema rechazando acceso a solicitudes de otros solicitantes
     *
     * @param solicitudId ID de la solicitud a consultar
     * @param solicitanteId ID del solicitante actual (propietario esperado)
     * @return Optional.of(Solicitud) si acceso autorizado, Optional.empty() en otro caso
     * @throws IllegalArgumentException si algún parámetro es null o inválido
     */
    @Transactional(readOnly = true)
    public Optional<Solicitud> obtenerDetalleSolicitud(Long solicitudId, Long solicitanteId) {
        // Validar parámetros
        if (solicitudId == null || solicitudId <= 0) {
            log.warn("Intento de obtener solicitud con ID inválido: {}", solicitudId);
            return Optional.empty();
        }

        if (solicitanteId == null || solicitanteId <= 0) {
            log.warn("Intento de obtener solicitud con solicitanteId inválido: {}", solicitanteId);
            return Optional.empty();
        }

        log.debug("Obteniendo detalle de solicitud ID: {} para solicitante ID: {}",
                solicitudId, solicitanteId);

        Optional<Solicitud> solicitud = solicitudRepository.findById(solicitudId)
                .filter(s -> {
                    boolean esPropietary = s.getSolicitante().getId().equals(solicitanteId);

                    if (!esPropietary) {
                        log.warn("ACCESO DENEGADO: Solicitante {} intentó acceder a solicitud {} que no le pertenece",
                                solicitanteId, solicitudId);
                    }

                    return esPropietary;
                });

        if (solicitud.isPresent()) {
            log.info("Solicitud {} consultada exitosamente por solicitante {}",
                    solicitudId, solicitanteId);
        } else {
            log.debug("Solicitud {} no encontrada o solicitante {} no es el propietario",
                    solicitudId, solicitanteId);
        }

        return solicitud;
    }

    public void eliminarSolicitud(Long id) {
        solicitudRepository.deleteById(id);
    }
}

package com.example.gr01_1bt3_622_26a.service;

import com.example.gr01_1bt3_622_26a.entity.Solicitud;
import com.example.gr01_1bt3_622_26a.repository.SolicitudRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.Optional;

@Service
@RequiredArgsConstructor
@Transactional
@Slf4j
public class SolicitudService {

    private final SolicitudRepository solicitudRepository;

    // Constantes de estado para evitar hardcoding
    private static final String ESTADO_EN_REVISION = "En revisión";
    private static final String ESTADO_APROBADA = "Aprobada";
    private static final String ESTADO_RECHAZADA = "Rechazada";

    /**
     *  REFACTOR: crearSolicitud mejorado
     *
     * Responsabilidades:
     * - Validar que la solicitud no sea nula
     * - Asignar automáticamente el estado "En revisión" (regla de negocio)
     * - Registrar en logs la creación
     * - Guardar la solicitud en la BD
     * - Retornar la solicitud creada
     *
     * Validaciones:
     * - Solicitud no puede ser null
     * - Se asigna estado automáticamente (cliente no puede definirlo)
     *
     * Logging:
     * - INFO: Solicitud creada exitosamente
     * - ERROR: Si hay error en persistencia
     *
     * @param solicitud la solicitud a crear (sin estado)
     * @return la solicitud guardada con estado "En revisión"
     * @throws IllegalArgumentException si solicitud es null
     */
    public Solicitud crearSolicitud(Solicitud solicitud) {
        // Validación: solicitud no puede ser nula
        if (solicitud == null) {
            log.warn("Intento de crear solicitud con valor null");
            throw new IllegalArgumentException("La solicitud no puede ser nula");
        }

        try {
            // Regla de negocio: toda solicitud nueva inicia en "En revisión"
            solicitud.setEstado(ESTADO_EN_REVISION);

            // Guardar en BD
            Solicitud solicitudGuardada = solicitudRepository.save(solicitud);

            // Logging: auditoría de creación
            Long solicitanteId = solicitudGuardada.getSolicitante() != null ?
                    solicitudGuardada.getSolicitante().getId() : null;
            log.info("Solicitud creada exitosamente con ID: {} para solicitante: {}",
                    solicitudGuardada.getId(), solicitanteId);

            return solicitudGuardada;

        } catch (Exception e) {
            Long solicitanteId = solicitud.getSolicitante() != null ?
                    solicitud.getSolicitante().getId() : null;
            log.error("Error al crear solicitud para solicitante: {}",
                    solicitanteId, e);
            throw new RuntimeException("No fue posible crear la solicitud. Por favor intente nuevamente.", e);
        }
    }

    @Transactional(readOnly = true)
    public Optional<Solicitud> obtenerPorId(Long id) {
        return solicitudRepository.findById(id);
    }

    @Transactional(readOnly = true)
    public List<Solicitud> obtenerPorSolicitante(Long solicitanteId) {
        return solicitudRepository.findBySolicitanteId(solicitanteId);
    }

    /**
     *  REFACTOR: Obtener solicitudes del solicitante
     *
     * TAREA 1: Listar solicitudes asociadas al solicitante
     *
     * Responsabilidades:
     * - Validar que el solicitanteId sea válido (positivo y no nulo)
     * - Buscar todas las solicitudes asociadas al solicitante
     * - Retornar lista nunca nula (puede estar vacía)
     * - Registrar en logs para auditoría
     *
     * Comportamiento:
     * - Acepta cualquier ID (positivo, cero o negativo)
     * - Si no hay solicitudes, retorna lista vacía (nunca null)
     * - Nivel de aislamiento: READ-ONLY para evitar modificaciones
     *
     * Casos de uso:
     * - Listar mis solicitudes (solicitante viendo su historial)
     * - Consultar solicitudes pendientes de un solicitante
     *
     * @param solicitanteId ID del solicitante propietario
     * @return Lista de Solicitud (nunca nula, puede estar vacía)
     */
    @Transactional(readOnly = true)
    public List<Solicitud> obtenerSolicitudesDelSolicitante(Long solicitanteId) {
        log.debug("Obteniendo solicitudes para solicitante ID: {}", solicitanteId);

        List<Solicitud> solicitudes = obtenerPorSolicitante(solicitanteId);

        log.info("Se encontraron {} solicitudes para solicitante ID: {}",
                solicitudes.size(), solicitanteId);

        return solicitudes;
    }

    @Transactional(readOnly = true)
    public List<Solicitud> obtenerPorMascota(Long mascotaId) {
        return solicitudRepository.findByMascotaId(mascotaId);
    }

    @Transactional(readOnly = true)
    public List<Solicitud> obtenerPorEstado(String estado) {
        return solicitudRepository.findByEstadoOrderByFecha(estado);
    }

    public Solicitud aprobarSolicitud(Long id) {
        log.info("Aprobando solicitud con ID: {}", id);
        return solicitudRepository.findById(id)
                .map(s -> {
                    s.setEstado(ESTADO_APROBADA);
                    Solicitud actualizada = solicitudRepository.save(s);
                    log.info("Solicitud {} aprobada exitosamente", id);
                    return actualizada;
                })
                .orElseGet(() -> {
                    log.warn("Intento de aprobar solicitud no existente con ID: {}", id);
                    return null;
                });
    }

    public Solicitud rechazarSolicitud(Long id, String razon) {
        log.info("Rechazando solicitud con ID: {} - Razón: {}", id, razon);
        return solicitudRepository.findById(id)
                .map(s -> {
                    s.setEstado(ESTADO_RECHAZADA);
                    s.setRazonRechazo(razon);
                    Solicitud actualizada = solicitudRepository.save(s);
                    log.info("Solicitud {} rechazada exitosamente", id);
                    return actualizada;
                })
                .orElseGet(() -> {
                    log.warn("Intento de rechazar solicitud no existente con ID: {}", id);
                    return null;
                });
    }

    public Solicitud actualizarSolicitud(Solicitud solicitud) {
        return solicitudRepository.save(solicitud);
    }

    @Transactional(readOnly = true)
    public List<Solicitud> obtenerTodas() {
        return solicitudRepository.findAll();
    }

    @Transactional(readOnly = true)
    public long contarPendientesParaMascota(Long mascotaId) {
        return solicitudRepository.countPendientesForMascota(mascotaId);
    }

    /**
     *  REFACTOR: Obtener detalle de solicitud con validación de propietario
     *
     * TAREA 2: Consultar el detalle de una solicitud específica
     *
     * Responsabilidades:
     * - Validar que ambos parámetros sean válidos (positivos y no nulos)
     * - Buscar la solicitud por ID
     * - Validar que el solicitante sea el propietario (seguridad)
     * - Retornar Optional con la solicitud o empty si no es propietario
     * - Registrar en logs intentos de acceso no autorizado
     *
     * Comportamiento:
     * - Retorna Optional.of(Solicitud) si el solicitante es propietario
     * - Retorna Optional.empty() si:
     *   1. La solicitud no existe
     *   2. El solicitante NO es el propietario (seguridad)
     * - Valida parámetros antes de consultar BD
     * - Registra accesos denegados para auditoría
     *
     * Validaciones de Seguridad:
     * - Previene que un solicitante vea solicitudes de otros
     * - Logging de intentos de acceso no autorizado
     *
     * Casos de uso:
     * - Un solicitante consultando el detalle de su propia solicitud
     * - Sistema rechazando acceso a solicitudes de otros solicitantes
     *
     * @param solicitudId ID de la solicitud a consultar
     * @param solicitanteId ID del solicitante actual (propietario esperado)
     * @return Optional.of(Solicitud) si acceso autorizado, Optional.empty() en otro caso
     * @throws IllegalArgumentException si algún parámetro es null o inválido
     */
    @Transactional(readOnly = true)
    public Optional<Solicitud> obtenerDetalleSolicitud(Long solicitudId, Long solicitanteId) {
        // Validar parámetros
        if (solicitudId == null || solicitudId <= 0) {
            log.warn("Intento de obtener solicitud con ID inválido: {}", solicitudId);
            return Optional.empty();
        }

        if (solicitanteId == null || solicitanteId <= 0) {
            log.warn("Intento de obtener solicitud con solicitanteId inválido: {}", solicitanteId);
            return Optional.empty();
        }

        log.debug("Obteniendo detalle de solicitud ID: {} para solicitante ID: {}",
                solicitudId, solicitanteId);

        Optional<Solicitud> solicitud = solicitudRepository.findById(solicitudId)
                .filter(s -> {
                    boolean esPropietary = s.getSolicitante().getId().equals(solicitanteId);

                    if (!esPropietary) {
                        log.warn("ACCESO DENEGADO: Solicitante {} intentó acceder a solicitud {} que no le pertenece",
                                solicitanteId, solicitudId);
                    }

                    return esPropietary;
                });

        if (solicitud.isPresent()) {
            log.info("Solicitud {} consultada exitosamente por solicitante {}",
                    solicitudId, solicitanteId);
        } else {
            log.debug("Solicitud {} no encontrada o solicitante {} no es el propietario",
                    solicitudId, solicitanteId);
        }

        return solicitud;
    }

    // ==================== FASE GREEN (T.1.3) - Métodos Mínimos ====================

    /**
     *  GREEN: Aprobar solicitud (Código mínimo para pasar test)
     *
     * Responsabilidades TDD básicas:
     * - Cambiar estado a "Aprobada"
     * - Asignar fecha de respuesta
     * - Retornar solicitud actualizada
     *
     * @param id ID de la solicitud
     * @param observaciones Observaciones opcionales
     * @return Solicitud con estado actualizado
     */
    public Solicitud aprobarSolicitud(Long id, String observaciones) {
        log.info(" [GREEN] Aprobando solicitud ID: {}", id);

        // Obtener solicitud
        Solicitud solicitud = solicitudRepository.findById(id)
                .orElseThrow(() -> new IllegalArgumentException("Solicitud no encontrada: " + id));

        // Cambiar estado
        solicitud.setEstado("Aprobada");
        solicitud.setFechaRespuesta(java.time.LocalDateTime.now());
        solicitud.setObservaciones(observaciones);

        // Guardar y retornar
        return solicitudRepository.save(solicitud);
    }

    /**
     *  GREEN: Rechazar solicitud (Código mínimo para pasar test)
     *
     * Responsabilidades TDD básicas:
     * - Validar que razon no esté vacía
     * - Cambiar estado a "Rechazada"
     * - Asignar razón de rechazo
     * - Retornar solicitud actualizada
     *
     * @param id ID de la solicitud
     * @param razon Razón de rechazo (obligatoria)
     * @return Solicitud con estado actualizado
     * @throws IllegalArgumentException si razon está vacía
     */
    public Solicitud rechazarSolicitud(Long id, String razon) {
        log.info(" [GREEN] Rechazando solicitud ID: {}", id);

        // Validación de parámetro obligatorio
        if (razon == null || razon.isBlank()) {
            log.warn("❌ Intento de rechazar solicitud sin razón");
            throw new IllegalArgumentException("La razón de rechazo es obligatoria");
        }

        // Obtener solicitud
        Solicitud solicitud = solicitudRepository.findById(id)
                .orElseThrow(() -> new IllegalArgumentException("Solicitud no encontrada: " + id));

        // Cambiar estado
        solicitud.setEstado("Rechazada");
        solicitud.setFechaRespuesta(java.time.LocalDateTime.now());
        solicitud.setRazonRechazo(razon);

        // Guardar y retornar
        return solicitudRepository.save(solicitud);
    }

    public void eliminarSolicitud(Long id) {
        solicitudRepository.deleteById(id);
    }
}

